  const m=score.measures[i];xml+='<measure number="'+(i+1)+'">';if(i===0){const [bt,bv]=score.time.split('/');xml+='<attributes><divisions>'+divisions+'</divisions><key><fifths>'+(KEYSPEC[score.key]||0)+'</fifths><mode>'+(/m$/.test(score.key)?'minor':'major')+'</mode></key><time><beats>'+bt+'</beats><beat-type>'+bv+'</beat-type></time><staves>'+staffs.length+'</staves><clef number="1"><sign>G</sign><line>2</line></clef>'+(score.twoStaves?'<clef number="2"><sign>F</sign><line>4</line></clef>':'')+'</attributes><direction><direction-type><metronome><beat-unit>'+(score.six?'eighth':'quarter')+'</beat-unit><per-minute>'+score.bpm+'</per-minute></metronome></direction-type><sound tempo="'+(score.six?score.bpm/2:score.bpm)+'"/></direction>';}
