  function sanitizeSettings(s={}){const out={};for(const k of ['autoGainControl','echoCancellation','noiseSuppression'])if(typeof s[k]==='boolean')out[k]=s[k];for(const k of ['sampleRate','sampleSize','channelCount','latency'])if(Number.isFinite(s[k]))out[k]=s[k];return out;}
  function measure(buffer){let sum=0,peak=0,clipped=0,count=0;for(let c=0;c<buffer.numberOfChannels;c++){const x=buffer.getChannelData(c);for(let i=0;i<x.length;i++){const a=Math.abs(x[i]);peak=Math.max(peak,a);sum+=x[i]*x[i];if(a>=.999)clipped++;count++;}}const rms=Math.sqrt(sum/Math.max(1,count));return {duration:buffer.duration,channels:buffer.numberOfChannels,sampleRate:buffer.sampleRate,peakDb:db(peak),rmsDb:db(rms),clipped,peak};}
  function recommend(m){if(!m||!Number.isFinite(m.peakDb)||m.peakDb< -65)return {db:null,message:'신호가 너무 작습니다. 잡음만 증폭하지 않도록 보정 추천을 보류합니다. 위치·입력 장치를 확인하고 다시 연주하세요.'};const gain=Math.round(Math.max(-24,Math.min(30,-6-m.peakDb))*2)/2;return {db:gain,message:m.clipped?'원본에 최대 진폭에 닿은 구간이 있습니다. 기기를 멀리 두고 다시 시험하세요. 이미 찌그러진 소리는 보정으로 복구되지 않습니다.':'강하게 연주한 시험 구간의 최대 음량에 약 6dB 여유를 둔 고정 보정값입니다. 다른 연주에서는 다시 시험하세요.'};}
