 function micActualText(data){if(!data)return '아직 마이크를 열지 않았습니다.';const s=data.settings;return [MicCore.agcText(data.mode,s),`입력: ${s.sampleRate?s.sampleRate.toLocaleString()+' Hz':'표본율 확인 불가'} · ${s.channelCount?s.channelCount+'채널':'채널 확인 불가'}`,`저장: ${data.mime||'브라우저 기본'} · ${data.actualBitrate?Math.round(data.actualBitrate/1000)+' kbps':'실제 비트레이트 확인 불가'} (요청 ${data.requestedBitrate/1000})`,'에코 제거: '+(typeof s.echoCancellation==='boolean'?(s.echoCancellation?'켜짐':'꺼짐'):'확인 불가')+' · 잡음 억제: '+(typeof s.noiseSuppression==='boolean'?(s.noiseSuppression?'켜짐':'꺼짐'):'확인 불가')].join('\n');}
